			<div key={word} style={{ inlineSize: '140px' }}>
				<p style={{ background: 'var(--docs-color-bg-subtle)', border: '1px solid var(--docs-color-border)', borderRadius: '8px', fontFamily: 'inherit', fontSize: '0.875rem', hyphens: 'auto', lineHeight: '1.5', margin: '0', overflowWrap: 'break-word', padding: '12px' }}>
					{word}
				</p>
			</div>
		))}
